<?php
namespace App\Controllers\Admin;use App\Core\Controller;use App\Helpers\AdminAuth;use App\Services\Shipping;
class Orders extends Controller {public function index():void{$this->handleCors();$this->admin();$rows=$this->db()->query('SELECT o.id,o.order_number,o.status,o.total,o.created_at,c.full_name customer_name,p.status payment_status,d.tracking_number,d.status delivery_status FROM vp_orders o INNER JOIN vp_customers c ON c.id=o.customer_id LEFT JOIN vp_payments p ON p.order_id=o.id LEFT JOIN vp_order_deliveries d ON d.order_id=o.id ORDER BY o.created_at DESC LIMIT 100')->result_array()?:[];$this->success(['items'=>$rows],'Orders loaded');}public function update_status($id=null):void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$a=$this->admin();$status=(string)($this->getBody()['status']??'');if(!in_array($status,['pending_payment','paid','processing','shipped','completed','cancelled','expired'],true))$this->error('Invalid status',422);$ok=$this->db()->update('vp_orders',['status'=>$status,'updated_at'=>$GLOBALS['now']??date('Y-m-d H:i:s')],['id'=>(int)$id]);if(!$ok)$this->error('Order not found',404);$this->success(null,'Order status updated');}public function save_delivery($id=null):void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$this->admin();$b=$this->getBody();$order=$this->db()->query('SELECT id FROM vp_orders WHERE id=? LIMIT 1',[(int)$id])->row_array();if(!$order)$this->error('Order not found',404);$now=$GLOBALS['now']??date('Y-m-d H:i:s');$data=['tracking_number'=>trim((string)($b['tracking_number']??''))?:null,'courier_company'=>trim((string)($b['courier_company']??''))?:null,'courier_service'=>trim((string)($b['courier_service']??''))?:null,'status'=>trim((string)($b['status']??'shipped')),'shipped_at'=>$now,'updated_at'=>$now];$existing=$this->db()->query('SELECT id FROM vp_order_deliveries WHERE order_id=? LIMIT 1',[(int)$id])->row_array();if($existing)$this->db()->update('vp_order_deliveries',$data,['id'=>(int)$existing['id']]);else $this->db()->insert('vp_order_deliveries',$data+['order_id'=>(int)$id,'created_at'=>$now]);$this->db()->update('vp_orders',['status'=>'shipped','updated_at'=>$now],['id'=>(int)$id]);$this->success(null,'Delivery saved');} public function show($id=null):void{$this->handleCors();$this->admin();$id=(int)$id;$o=$this->db()->query('SELECT o.*,c.full_name customer_name,c.email customer_email,c.phone customer_phone FROM vp_orders o INNER JOIN vp_customers c ON c.id=o.customer_id WHERE o.id=? LIMIT 1',[$id])->row_array();if(!$o)$this->error('Order not found',404);$o['id']=(int)$o['id'];$o['subtotal']=(float)$o['subtotal'];$o['shipping_cost']=(float)$o['shipping_cost'];$o['total']=(float)$o['total'];$o['recipient']=json_decode((string)($o['recipient_snapshot']??''),true)?:[];unset($o['recipient_snapshot']);$items=$this->db()->query('SELECT id,product_name,selections_snapshot,quantity,unit_price,total_price FROM vp_order_items WHERE order_id=? ORDER BY id',[$id])->result_array()?:[];foreach($items as &$it){$it['id']=(int)$it['id'];$it['quantity']=(int)$it['quantity'];$it['unit_price']=(float)$it['unit_price'];$it['total_price']=(float)$it['total_price'];$it['selections']=json_decode((string)($it['selections_snapshot']??''),true)?:[];unset($it['selections_snapshot']);}unset($it);$o['items']=$items;$p=$this->db()->query('SELECT status,transaction_id,payment_type,gross_amount,paid_at FROM vp_payments WHERE order_id=? LIMIT 1',[$id])->row_array();if($p)$p['gross_amount']=(float)$p['gross_amount'];$o['payment']=$p;$o['delivery']=$this->db()->query('SELECT tracking_number,courier_company,courier_service,status,shipped_at,delivered_at FROM vp_order_deliveries WHERE order_id=? LIMIT 1',[$id])->row_array();$this->success($o,'Order loaded');}
 public function mark_paid($id=null):void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$this->admin();$id=(int)$id;if(!$this->db()->query('SELECT id FROM vp_orders WHERE id=? LIMIT 1',[$id])->row_array())$this->error('Order not found',404);$now=$GLOBALS['now']??date('Y-m-d H:i:s');$p=$this->db()->query('SELECT id FROM vp_payments WHERE order_id=? LIMIT 1',[$id])->row_array();if($p)$this->db()->update('vp_payments',['status'=>'paid','paid_at'=>$now,'updated_at'=>$now],['id'=>(int)$p['id']]);else $this->db()->insert('vp_payments',['order_id'=>$id,'provider'=>'manual','gross_amount'=>0,'status'=>'paid','paid_at'=>$now,'created_at'=>$now,'updated_at'=>$now]);$this->db()->update('vp_orders',['status'=>'processing','updated_at'=>$now],['id'=>$id]);$this->success(null,'Pesanan ditandai lunas');}
 public function book($id=null):void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$this->admin();$id=(int)$id;$order=$this->db()->query('SELECT * FROM vp_orders WHERE id=? LIMIT 1',[$id])->row_array();if(!$order)$this->error('Order not found',404);try{$r=Shipping::bookBiteship($this->db(),$order);if(in_array($order['status'],['paid','processing','pending_payment'],true))$this->db()->update('vp_orders',['status'=>'shipped','updated_at'=>$GLOBALS['now']??date('Y-m-d H:i:s')],['id'=>$id]);$this->success($r,'Pesanan dikirim');}catch(\Throwable $e){$this->error($e->getMessage(),422);}}
 public function mark_completed($id=null):void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$this->admin();$id=(int)$id;$ok=$this->db()->update('vp_orders',['status'=>'completed','updated_at'=>$GLOBALS['now']??date('Y-m-d H:i:s')],['id'=>$id]);if(!$ok)$this->error('Order not found',404);$this->success(null,'Pesanan selesai');}
 public function cancel($id=null):void{$this->handleCors();if(!$this->isPost())$this->error('Method not allowed',405);$this->admin();$id=(int)$id;$note=trim((string)($this->getBody()['note']??''))?:null;$order=$this->db()->query('SELECT id FROM vp_orders WHERE id=? LIMIT 1',[$id])->row_array();if(!$order)$this->error('Order not found',404);$now=$GLOBALS['now']??date('Y-m-d H:i:s');$this->db()->update('vp_orders',['status'=>'cancelled','admin_note'=>$note,'updated_at'=>$now],['id'=>$id]);$this->db()->update('vp_payments',['status'=>'cancelled','updated_at'=>$now],['order_id'=>$id]);$this->success(null,'Pesanan dibatalkan');}
 private function admin():array{$a=AdminAuth::user();if(!$a)$this->error('Unauthorized',401);return $a;}}
